SourceCode.Declaration:
[TFMDescription("Executes an expression using a field on a table or other objects in the context")]
class TFMLogicContextExecuteExpression extends TFMLogicContextObject
{
}

Method.Source:
protected void new()
{
    super();

    outputType = TFMLogicContextTypes::String;
    noOfInput = 0;
    categories.add("Data");
}

public Object process(TFMExpression _expression = '', TableName _tableName = '', TFMFlowVariableContextLookupField _value = '')
{
    Common  record;
    str	    inputValue;
    Map	    resultMap = new Map(Types::String, Types::String);
    if (_tableName)
    {
        record = context.getTableFromAnyBlock(_tableName);
    }

    if (_value)
    {
        inputValue = context.replaceWithValue(_value);
    }
    resultMap.insert('', TFMExpressions::evaluateExpression(_expression, record, inputValue)); // When no key is specified, return the result with an empty string key
    return resultMap;

}
